css:
.mss { font-size: 10.5px; color: #000; }
.mss h2 { font-size: 15px; margin: 0 0 4px; }
.mss h3 { font-size: 11.5px; margin: 7px 0 3px; padding-bottom: 1px; border-bottom: 1px solid #000; }
.mss table { width: 100%; border-collapse: collapse; margin: 0 0 3px !important; }
.print-format .mss td, .print-format .mss th { padding: 2px 5px !important; line-height: 1.35; }
.mss .grid th, .mss .grid td { border: 1px solid #999; }
.mss .grid th { background: #eee; text-align: left; font-weight: 600; }
.mss .small { font-size: 9.5px; }
.mss .r { text-align: right; white-space: nowrap; }
.mss .b td { font-weight: bold; }
.mss .two > tbody > tr > td { width: 50%; vertical-align: top; padding: 0 6px 0 0 !important; border: 0; }
.mss .sign { margin-top: 18px !important; border-collapse: separate; border-spacing: 10px 0; page-break-inside: avoid; }
.print-format .mss .sign td { width: 25%; padding: 26px 2px 0 !important; border-top: 1px solid #000; text-align: center; vertical-align: top; }
